INSERT OR IGNORE INTO artists (id, name, alias, type, genres, country, location, descr, bio, photo, poster, instagram, sort_order, published, updated_at) VALUES (1, 'Stephanno Jr.', NULL, 'DJ', '["Afro House", "Afro Tech", "Deep House"]', 'Romania', 'Romania', 'DJ, producer and founder of Hidden State.', 'As a DJ, producer and founder of Hidden State and all its divisions, Stephanno Jr. continues to build his own universe within the electronic music scene — connecting music, events, artists and creative experiences under one vision. Bringing his signature sound across Afro House, Afro Tech and Deep House, he plays with a sound shaped by years behind the decks and a constant drive to create something of his own.', '/portrait.webp', '/news/posters/stephanno-astryon.webp', 'stephannojr', 0, 1, datetime('now'));
INSERT OR IGNORE INTO artists (id, name, alias, type, genres, country, location, descr, bio, photo, poster, instagram, sort_order, published, updated_at) VALUES (2, 'DJ Tengu', NULL, 'DJ', '["Old School Hip-Hop", "R&B", "Funk", "Soul", "Classic Urban"]', NULL, NULL, 'Old soul, real music, new energy.', 'DJ Tengu is driven by passion, talent, and a genuine love for music. With experience behind the decks and an unmistakable old-school spirit, he brings a sound that connects generations and keeps the energy alive. His selections travel through the golden sounds of old school hip-hop, R&B, funk, soul, rap and classic urban music, blending timeless records with his own style and personality. For DJ Tengu, music is more than just playing tracks — it''s about creating an atmosphere, telling a story and making people feel every beat.', '/news/dj-tengu.webp', '/news/posters/dj-tengu.webp', 'djtengu', 1, 1, datetime('now'));
INSERT OR IGNORE INTO artists (id, name, alias, type, genres, country, location, descr, bio, photo, poster, instagram, sort_order, published, updated_at) VALUES (3, 'Mario Daniel', 'DJ Mario', 'DJ', '["Afro House", "House"]', NULL, NULL, 'Deep grooves, rhythm and energy.', 'DJ Mario brings together the energy, warmth and hypnotic character of Afro House in sets designed to be felt from beginning to end. With a carefully selected tracklist, flowing transitions and a strong focus on rhythm, his Fill & Dance set explores the deeper and more energetic side of Afro House — moving naturally between atmospheric moments, powerful grooves and uplifting rhythms. More than a collection of tracks, it captures his approach to music: letting the rhythm build naturally while keeping the energy alive throughout the entire journey.', '/artists/dj-mario.webp', '/news/posters/dj-mario.webp', 'djmario', 2, 1, datetime('now'));
INSERT OR IGNORE INTO artists (id, name, alias, type, genres, country, location, descr, bio, photo, poster, instagram, sort_order, published, updated_at) VALUES (4, 'B.MIKE', 'Heartbeat Vibes', 'DJ', '["2000s Retro", "EDM", "House", "Tech-House", "Drum & Bass"]', 'Romania', 'Romania', 'Turning passion into ability, and ability into music.', 'B.MIKE started DJing in 2022 and is part of OWPN Academy. Since then he has played major festivals including UNTOLD, Electric Castle, Flight Festival, Take Off Festival, Codru Festival, Snow Fest France, Nassau Festival, Univibes and Takeover, alongside venues across Romania such as Fratelli Timisoara, Form Space Cluj and Underground Pub Iasi — sharing stages with Carla''s Dreams, DJ Project, Alina Eremia, Feli, Elena Gheorghe and Lidia Buble. His awards include the Timisoara Music Awards New Talent Award (2023) and Tech-House Award (2024), a place among the five Drum & Bass finalists (2025), and an Excellence Award from Flight Festival in 2025. Since March 2026 he has been part of EPICA, a charitable music project alongside Pascal Junior, Jayko, Silviu Andrei and Mindblow. His sets move between 2000s retro, EDM, house, tech-house and drum & bass, running anywhere from 128 to 175 BPM.', '/artists/b-mike.webp', '/news/posters/b-mike.webp', 'bmike', 3, 1, datetime('now'));
INSERT OR IGNORE INTO artists (id, name, alias, type, genres, country, location, descr, bio, photo, poster, instagram, sort_order, published, updated_at) VALUES (5, 'DJ Stephanno', 'Model 1', 'DJ', '["House", "Techno", "Vinyl"]', 'Romania', 'Romania', 'Two decades of experience. One passion. Pure vinyl.', 'With over 20 years behind the decks, DJ Stephanno / Model 1 is a true lover of the art of DJing. A vinyl-driven artist with a deep connection to the roots of electronic music, he brings together the timeless character of house and techno with experience, instinct and an authentic underground spirit. His sets are built around groove, atmosphere and storytelling, allowing the music to speak naturally and the dancefloor to become part of the journey.', '/artists/dj-stephanno-model1.webp', '/news/posters/dj-stephanno-model1.webp', 'djstephanno', 4, 1, datetime('now'));
INSERT OR IGNORE INTO artists (id, name, alias, type, genres, country, location, descr, bio, photo, poster, instagram, sort_order, published, updated_at) VALUES (6, 'Tess Wich', 'Tech Wich', 'DJ', '["Hard Techno", "Peak-Time", "Hard Bounce", "Rave"]', 'Australia', 'Australia', 'Dark atmospheres, hypnotic grooves, built for the dancefloor.', 'Australian DJ and electronic music artist, performing as Tech Wich. Known for her powerful hard techno, peak-time, hard bounce and rave sound, Tess brings dark atmospheres, hypnotic grooves and high-energy sets built for the dancefloor. With a distinctive visual identity and an evolving international presence, she is quickly making her mark on the global techno scene.', '/artists/tess-wich.webp', '/news/posters/tess-wich.webp', 'tesswich', 5, 1, datetime('now'));
INSERT OR IGNORE INTO artists (id, name, alias, type, genres, country, location, descr, bio, photo, poster, instagram, sort_order, published, updated_at) VALUES (7, 'Claire Cruz', NULL, 'DJ', '["Afro House", "Melodic Techno", "Tribal"]', 'United Arab Emirates', 'Dubai', 'Afro House and melodic techno with a dark, hypnotic edge.', 'Filipino-Spanish DJ and producer based in Dubai, and founder of Impact Studio FZE and InfluencersDubai.AE. She stepped into music after a career across events, marketing and influencer management. Her debut single, “Pearl of Sand,” introduces a sound blending Afro House, melodic techno and tribal elements into a dark, hypnotic atmosphere. Following her debut she is set to take her music beyond Dubai, with Romania marking her first festival performance in Europe and outside the UAE.', '/artists/claire-cruz.webp', '/news/posters/claire-cruz.webp', 'clairecruz', 6, 1, datetime('now'));
INSERT OR IGNORE INTO records (slug, title, artist, kind, tagline, catalog, release_date, cover, playlist, note, tracks, sort_order, published, updated_at) VALUES ('aymara', 'AYMARA', 'Stephanno Jr.', 'ALBUM', 'sounds of hearts', 'HS-001', NULL, '/records/aymara.webp', 'https://www.youtube.com/playlist?list=PLboGw-g1tS4k', 'Six tracks built around rhythm and atmosphere — the first full-length release on Hidden State Records.', '[{"n": 1, "title": "Kasbah", "cover": "/records/kasbah.webp", "youtube": "SPWGalk7gW4"}, {"n": 2, "title": "Mestizo", "cover": "/records/mestizo.webp", "youtube": "Qo5dlQ5_ano"}, {"n": 3, "title": "Nenge", "cover": "/records/nenge.webp", "youtube": "1fhB8U8P6mA"}, {"n": 4, "title": "Aymara", "cover": "/records/aymara.webp", "youtube": "Qq3ipZDiENE"}, {"n": 5, "title": "To The Unknown", "cover": "/records/to-the-unknown.webp", "youtube": "er3TTUZS87s"}, {"n": 6, "title": "Sing Chu", "cover": "/records/sing-chu.webp", "youtube": "elLTDFL5L1Q"}]', 0, 1, datetime('now'));
INSERT OR IGNORE INTO records (slug, title, artist, kind, tagline, catalog, release_date, cover, playlist, note, tracks, sort_order, published, updated_at) VALUES ('pearl-of-sand', 'PEARL OF SAND', 'Claire Cruz', 'SINGLE', 'a dark, hypnotic atmosphere', 'HS-002', NULL, '/artists/claire-cruz.webp', 'https://www.youtube.com/watch?v=uJR9jclSYMU', 'Claire Cruz''s debut single, blending Afro House, melodic techno and tribal elements.', '[{"n": 1, "title": "Pearl of Sand", "cover": "/artists/claire-cruz.webp", "youtube": "uJR9jclSYMU"}]', 1, 1, datetime('now'));
INSERT OR IGNORE INTO mixes (slug, artist_id, name, alias, photo, genres, intro, coming_soon, coming_soon_note, sections, sort_order, published, updated_at) VALUES ('stephanno-jr', 1, 'Stephanno Jr.', NULL, '/portrait.webp', '["Afro House", "Afro Tech", "Deep House"]', 'Recorded sets from the founder of Hidden State — Afro House, Afro Tech and Deep House, built around rhythm and the long build.', 0, NULL, '[{"label": null, "items": [{"title": "Set 01", "url": "https://youtu.be/dmfmefK6UQM"}, {"title": "Set 02", "url": "https://youtu.be/U9fzm1eR2rQ"}]}]', 0, 1, datetime('now'));
INSERT OR IGNORE INTO mixes (slug, artist_id, name, alias, photo, genres, intro, coming_soon, coming_soon_note, sections, sort_order, published, updated_at) VALUES ('dj-tengu', 2, 'DJ Tengu', NULL, '/news/dj-tengu.webp', '["Old School Hip-Hop", "R&B", "Funk", "Soul"]', 'Old soul, real music, new energy. Tengu''s sets travel through the golden sounds of hip-hop, R&B, funk and soul.', 0, NULL, '[{"label": "90''s Hip-Hop & R&B", "items": [{"title": "Urban Nation \u2014 90''s R&B Edition 02", "url": "https://www.mixcloud.com/dj-league/urban-nation-dj-tengu-rou-90iesrbedition-02/"}, {"title": "Urban Nation \u2014 90''s R&B Edition 03", "url": "https://www.mixcloud.com/dj-league/urban-nation-dj-tengu-rou-90iesrbedition-03/"}, {"title": "Urban Nation \u2014 90''s R&B Edition 04", "url": "https://www.mixcloud.com/dj-league/urban-nation-dj-tengu-rou-90iesrbedition-04/"}, {"title": "Urban Nation \u2014 90''s R&B Edition 05", "url": "https://www.mixcloud.com/dj-league/urban-nation-dj-tengu-rou-90iesrbedition-05/"}, {"title": "Urban Nation \u2014 07", "url": "https://www.mixcloud.com/dj-league/urban-nation-dj-tengu-rou-7/"}]}, {"label": "80''s \u2013 90''s Classic Funk", "items": [{"title": "Urban Nation \u2014 Classic Funk Edition 01", "url": "https://www.mixcloud.com/dj-league/urban-nation-dj-tengu-rou-classicfunkedition-01/"}, {"title": "Urban Nation \u2014 Classic Funk Edition 04", "url": "https://www.mixcloud.com/dj-league/urban-nation-dj-tengu-rou-classicfunkedition-04/"}, {"title": "Urban Nation \u2014 Classic Funk Edition 06", "url": "https://www.mixcloud.com/dj-league/urban-nation-dj-tengu-rou-classicfunkedition-06/"}]}]', 1, 1, datetime('now'));
